"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronDown, 
  CheckCircle2, 
  UploadCloud, 
  UserCheck
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" }
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", balance: 18, requiresDoc: false },
  { id: "sick", label: "Sick Leave", balance: 12, requiresDoc: true },
  { id: "casual", label: "Casual Leave", balance: 6, requiresDoc: false },
  { id: "comp_off", label: "Compensatory Off", balance: 3, requiresDoc: false },
  { id: "maternity", label: "Maternity/Paternity", balance: 90, requiresDoc: true },
  { id: "bereavement", label: "Bereavement", balance: 5, requiresDoc: false },
  { id: "unpaid", label: "Loss of Pay (L.O.P)", balance: 0, requiresDoc: false },
];

export default function SimpleEliteAbsence() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [halfDay, setHalfDay] = useState<"am" | "pm" | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
      setHalfDay(null);
    } else {
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  const stats = useMemo(() => {
    if (!range.start || !range.end) return { days: 0, deduction: 0 };
    
    let deduction = 0;
    let days = 0;
    let cur = new Date(range.start);
    let end = new Date(range.end);

    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const isHoliday = HOLIDAYS.some(h => h.date === dateStr);
      const isWeekend = cur.getDay() === 0 || cur.getDay() === 6;

      if (!isHoliday && !isWeekend) {
        deduction += (range.start === range.end && halfDay) ? 0.5 : 1;
      }
      days++;
      cur.setDate(cur.getDate() + 1);
    }
    return { days, deduction };
  }, [range, halfDay]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    // MAIN CONTAINER: Added dark:bg-black and dark:text-slate-100
    <div className="flex h-screen w-full flex-col bg-[#F8FAFC] dark:bg-black text-slate-800 dark:text-slate-100 overflow-hidden font-sans transition-colors duration-200">
      
      {/* --- LEFT: CALENDAR (70%) --- */}
      <div className="flex-1 flex flex-col p-6 pr-0 gap-6">
        
        {/* Header with Mode Switcher */}
        <div className="flex items-center justify-between">
           <div>
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Request Absence</h1>
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Select your dates on the calendar</p>
           </div>
           
           {/* SWITCHER: Added dark borders and backgrounds */}
           <div className="bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 flex">
              <button 
                onClick={() => { setMode("single"); setRange({start:"", end:""}); }}
                className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "single" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Single Day
              </button>
              <button 
                onClick={() => { setMode("range"); setRange({start:"", end:""}); }}
                className={`px-5 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "range" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Date Range
              </button>
           </div>
        </div>

        {/* Large Calendar Canvas */}
        {/* CONTAINER: Dark background and dark borders */}
        <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden">
           <div className="flex items-center justify-between px-8 py-6 border-b border-slate-100 dark:border-slate-800">
              <h2 className="text-xl font-bold text-slate-800 dark:text-white">January 2026</h2>
              <div className="flex gap-4 text-[10px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500">
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-slate-900 dark:bg-blue-600"/>Selected</div>
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-rose-500"/>Holiday</div>
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-slate-200 dark:bg-slate-700"/>Weekend</div>
              </div>
           </div>

           <div className="flex-1 p-8">
              <div className="grid grid-cols-7 gap-3 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 uppercase mb-2">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                    const isSelected = range.start === dateStr || range.end === dateStr;
                    const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         className={`
                           relative h-full min-h-[60px] rounded-2xl border text-left p-3 transition-all group
                           ${isSelected 
                              ? "bg-slate-900 dark:bg-blue-600 text-white border-slate-900 dark:border-blue-600 shadow-xl scale-105 z-10" 
                              : ""}
                           ${inRange 
                              ? "bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-200 border-blue-100 dark:border-blue-800" 
                              : ""}
                           ${!isSelected && !inRange && holiday 
                              ? "bg-rose-50 dark:bg-rose-900/20 border-rose-100 dark:border-rose-900/50" 
                              : ""}
                           ${!isSelected && !inRange && isWeekend 
                              ? "bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-300 dark:text-slate-600" 
                              : "bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-blue-400 dark:hover:border-blue-500"}
                         `}
                       >
                          <span className="text-sm font-bold">{day}</span>
                          {holiday && <span className={`absolute bottom-2 left-2 text-[9px] font-bold px-1.5 py-0.5 rounded ${isSelected ? "bg-white/20 text-white" : "bg-rose-100 dark:bg-rose-900/50 text-rose-600 dark:text-rose-300"}`}>{holiday.name}</span>}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>
      </div>

      {/* --- RIGHT: CONTROL PANEL (30% / 400px fixed) --- */}
      <div className="w-[400px] flex-none p-6 flex flex-col gap-6">
         
         {/* 1. Details Card */}
         {/* CONTAINER: Dark background */}
         <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden">
            <div className="p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30">
               <h3 className="text-xs font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500 mb-4">Request Details</h3>
               
               {/* DROP DOWN: Dark mode friendly inputs */}
               <div className="relative">
                  <select 
                    value={typeId}
                    onChange={(e) => setTypeId(e.target.value)}
                    className="w-full appearance-none bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white text-sm font-bold rounded-xl p-4 pr-10 focus:ring-2 focus:ring-slate-900 dark:focus:ring-blue-500 outline-none cursor-pointer"
                  >
                     {LEAVE_TYPES.map(t => (
                        <option key={t.id} value={t.id}>{t.label} (Bal: {t.balance})</option>
                     ))}
                  </select>
                  <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 pointer-events-none" />
               </div>
            </div>

            <div className="flex-1 p-6 space-y-6 overflow-y-auto">
               
               {/* Summary Stats */}
               <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-4 border border-slate-100 dark:border-slate-700 space-y-2">
                  <div className="flex justify-between items-center">
                     <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">Leave Balance</span>
                     <span className="text-xs font-bold text-slate-900 dark:text-white">{selectedType.balance} Days</span>
                  </div>
                  <div className="flex justify-between items-center">
                     <span className="text-xs text-slate-500 dark:text-slate-400 font-medium">Deduction</span>
                     <span className="text-xs font-bold text-rose-500">-{stats.deduction} Days</span>
                  </div>
                  <div className="h-px bg-slate-200 dark:bg-slate-700 my-1"/>
                  <div className="flex justify-between items-center">
                     <span className="text-xs font-bold text-slate-700 dark:text-slate-300">Remaining</span>
                     <span className="text-sm font-black text-slate-900 dark:text-white">{selectedType.balance - stats.deduction} Days</span>
                  </div>
               </div>

               {/* Half Day Toggle (Conditional) */}
               {mode === "single" && range.start && (
                  <div className="animate-in fade-in">
                     <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Duration</label>
                     <div className="grid grid-cols-3 gap-2 bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                        {/* Toggle Buttons: Handle Dark Mode State */}
                        <button onClick={() => setHalfDay(null)} className={`text-[10px] font-bold py-2 rounded ${!halfDay ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400"}`}>Full Day</button>
                        <button onClick={() => setHalfDay("am")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "am" ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400"}`}>1st Half</button>
                        <button onClick={() => setHalfDay("pm")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "pm" ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400"}`}>2nd Half</button>
                     </div>
                  </div>
               )}

               {/* Reason */}
               <div>
                  <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Reason</label>
                  <textarea 
                     className="w-full h-24 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-950 p-3 text-xs font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-slate-900 dark:focus:ring-blue-500 outline-none resize-none"
                     placeholder="Brief reason for your absence..."
                     value={reason}
                     onChange={(e) => setReason(e.target.value)}
                  />
               </div>

               {/* Attachment (Conditional) */}
               {selectedType.requiresDoc && (
                  <div className="animate-in zoom-in-95">
                     <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block flex justify-between">
                        <span>Attachment</span> <span className="text-rose-500">* Required</span>
                     </label>
                     <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`border-2 border-dashed rounded-xl h-16 flex items-center justify-center cursor-pointer transition-colors gap-2 ${
                           file 
                           ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20" 
                           : "border-slate-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800"
                        }`}
                     >
                        <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                        {file ? (
                           <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1"><CheckCircle2 className="h-4 w-4"/> {file.name}</span>
                        ) : (
                           <>
                             <UploadCloud className="h-4 w-4 text-slate-400" />
                             <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400">Upload Proof</span>
                           </>
                        )}
                     </div>
                  </div>
               )}
            </div>
            
            {/* Submit Section */}
            <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/30">
               <button 
                  disabled={!range.start || (selectedType.requiresDoc && !file)}
                  className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-xl font-bold text-sm shadow-lg hover:bg-black dark:hover:bg-blue-500 disabled:bg-slate-300 dark:disabled:bg-slate-800 dark:disabled:text-slate-500 transition-all mb-4"
               >
                  Submit Request
               </button>
               
               <div className="flex items-center justify-center gap-2 opacity-60">
                  <UserCheck className="h-3 w-3 text-slate-500 dark:text-slate-400" />
                  <span className="text-[10px] font-medium text-slate-500 dark:text-slate-400">Approver: Sarah Jenkins</span>
               </div>
            </div>
         </div>

      </div>
    </div>
  );
}